# infeasible_test.py
# PyTest-style test to verify handling of infeasible resource capacities
from production_model import build_and_solve_model

def test_build_and_solve_model_infeasible_capacities():
    # Reuse the same minimal dataset as the functional test (first 5 complete products)
    product_ids = ['PROD_001','PROD_002','PROD_003','PROD_004','PROD_005']

    profit = {'PROD_001': 11.62,'PROD_002': 41.03,'PROD_003': 30.31,'PROD_004': 47.13,'PROD_005': 50.78}
    machineA = {'PROD_001': 0.08,'PROD_002': 2.37,'PROD_003': 2.32,'PROD_004': 0.3,'PROD_005': 0.67}
    machineB = {'PROD_001': 0.40,'PROD_002': 1.85,'PROD_003': 0.48,'PROD_004': 0.85,'PROD_005': 2.60}
    labor = {'PROD_001': 2.45,'PROD_002': 3.51,'PROD_003': 2.81,'PROD_004': 2.77,'PROD_005': 4.02}
    material = {'PROD_001': 4.0,'PROD_002': 9.0,'PROD_003': 7.0,'PROD_004': 2.0,'PROD_005': 26.0}
    min_prod = {'PROD_001': 0,'PROD_002': 0,'PROD_003': 20,'PROD_004': 0,'PROD_005': 0}
    max_demand = {'PROD_001': 224,'PROD_002': 81,'PROD_003': 221,'PROD_004': 269,'PROD_005': 75}

    data = {
        'product_ids': product_ids,
        'profit': profit,
        'machineA': machineA,
        'machineB': machineB,
        'labor': labor,
        'material': material,
        'min_prod': min_prod,
        'max_demand': max_demand
    }

    # Set all capacities to zero: model should be infeasible because product PROD_003 requires a min_prod of 20
    capacities_zero = {
        'total_machineA_hours': 0.0,
        'total_machineB_hours': 0.0,
        'total_labor_hours': 0.0,
        'total_material_units': 0.0
    }

    solution = build_and_solve_model(data, capacities_zero, integer_vars=False)

    # The solver should report infeasible (feasible flag False); ensure graceful handling
    assert isinstance(solution, dict)
    # Either the solver marks infeasible (feasible==False) or it returns a status that is not Optimal/Feasible
    assert solution.get('feasible') is False, f"Expected infeasible result, got feasible={solution.get('feasible')} and status={solution.get('status')}"

    # Optionally: when infeasible, produced quantities may be None or the solver may not set objective; ensure no uncaught exceptions occurred
    # (If the implementation changes to raise on infeasibility, adjust this test to expect ValueError.)
